 SELECT pos,token FROM posexplode(regexp_extract_all(s,r'&(?:#[0-9]+;?|#[xX][0-9a-fA-F]+;?|[^\t\n\f <&#;]{1,32};?)|[^&]+|&',0)) AS t(pos,token)
), entities AS (SELECT decode(unhex(entity),'UTF-8') entity,decode(unhex(value),'UTF-8') value FROM VALUES ('416163757465','c381'),
