('7a776e6a3b','e2808c') AS e(entity,value)),
invalid AS (SELECT code,decode(unhex(value),'UTF-8') value FROM VALUES (0L,'efbfbd'),
(13L,'0d'),
(128L,'e282ac'),
(129L,'c281'),
(130L,'e2809a'),
(131L,'c692'),
(132L,'e2809e'),
(133L,'e280a6'),
