-- FILE 044_name_stage.sql
-- REVIEW ONLY; owner Rohan; each production action requires fresh authorization.
-- immutable release stage cell 3
-- name_twin_merges: mirrors only the reviewed merge rows in edits.csv.
-- All 59 reviewed merges are deferred; this release preserves every owner.
CREATE TABLE openalex.funders.nm1013_integrated_merges AS
SELECT CAST(NULL AS BIGINT) loser_id,CAST(NULL AS BIGINT) survivor_id WHERE false;

-- FILE 045_name_stage.sql
-- REVIEW ONLY; owner Rohan; each production action requires fresh authorization.
-- immutable release stage cell 4
SELECT assert_true(count(*)=0 AND count_if(l.funder_id IS NULL OR w.funder_id IS NULL OR l.merge_into_id IS NOT NULL OR w.merge_into_id IS NOT NULL OR (l.ror_id IS NOT NULL AND w.ror_id IS NOT NULL AND l.ror_id<>w.ror_id))=0,'merge preconditions changed')
FROM openalex.funders.nm1013_integrated_merges m
LEFT JOIN openalex.funders.nm1013_integrated_catalogue_before l ON l.funder_id=m.loser_id
LEFT JOIN openalex.funders.nm1013_integrated_catalogue_before w ON w.funder_id=m.survivor_id;
SELECT assert_true(count(*)=0,'incoming redirects require renewed merge review') FROM openalex.funders.nm1013_integrated_catalogue_before f JOIN openalex.funders.nm1013_integrated_merges m ON f.merge_into_id=m.loser_id;
CREATE TABLE openalex.funders.nm1013_integrated_catalogue_after AS
SELECT f.* EXCEPT(merge_into_id),coalesce(m.survivor_id,f.merge_into_id) merge_into_id
FROM openalex.funders.nm1013_integrated_catalogue_before f
LEFT JOIN openalex.funders.nm1013_integrated_merges m ON m.loser_id=f.funder_id;
CREATE TABLE openalex.funders.nm1013_integrated_identifiers AS
SELECT 'ror' id_type,ror_id id_value,funder_id,funder_id origin_funder_id
FROM openalex.funders.nm1013_integrated_catalogue_before WHERE ror_id IS NOT NULL;
CREATE TABLE openalex.funders.nm1013_integrated_registry_after AS SELECT f.funder_id AS funder_id,CASE WHEN m.loser_id IS NOT NULL THEN 'merged' ELSE f.status END AS status,coalesce(m.survivor_id,f.merged_into_id) AS merged_into_id,f.ror_id AS ror_id,f.ror_primary AS ror_primary,f.parent_id AS parent_id,f.display_name AS display_name,f.alt_names AS alt_names,f.country_code AS country_code,f.homepage_url AS homepage_url,f.wikidata_id AS wikidata_id,f.description AS description,f.image_url AS image_url,f.image_thumbnail_url AS image_thumbnail_url,f.created_date AS created_date,CASE WHEN m.loser_id IS NOT NULL THEN current_timestamp() ELSE f.updated_date END AS updated_date,f.created_by AS created_by,CASE WHEN m.loser_id IS NOT NULL THEN 'openalex.funders.nm1013_integrated_' ELSE f.run_id END AS run_id,f.mint_key AS mint_key FROM openalex.funders.nm1013_integrated_registry_before f LEFT JOIN openalex.funders.nm1013_integrated_merges m ON f.funder_id=m.loser_id OR f.merged_into_id=m.loser_id;
CREATE TABLE openalex.funders.nm1013_integrated_identifiers_after AS SELECT f.id_type AS id_type,f.id_value AS id_value,coalesce(m.survivor_id,f.funder_id) AS funder_id,f.origin_funder_id AS origin_funder_id,f.is_primary AS is_primary,f.source AS source,f.added_at AS added_at,CASE WHEN m.loser_id IS NOT NULL THEN 'openalex.funders.nm1013_integrated_' ELSE f.run_id END AS run_id FROM openalex.funders.nm1013_integrated_identifiers_before f LEFT JOIN openalex.funders.nm1013_integrated_merges m ON f.funder_id=m.loser_id AND f.id_type NOT IN ('name','ror_cleared');
SELECT assert_true(count(*)=0,'duplicate identifier key') FROM (SELECT id_type,id_value FROM openalex.funders.nm1013_integrated_identifiers_before GROUP BY ALL HAVING count(*)<>1);

-- FILE 046_name_stage.sql
-- REVIEW ONLY; owner Rohan; each production action requires fresh authorization.
-- immutable release stage cell 5
-- name_lookup: ROR/exact remain ahead of hierarchy, reviewed aliases, twins, programmes.
-- All-ROR names and broad normalization are ONLY used for pipe-delimited leaves.
-- No country/fuzzy matching and no nm1012_jev_* inputs: Jev requires a new gate.
CREATE TABLE openalex.funders.nm1013_integrated_lookup_rows AS
WITH f AS (SELECT f.*, CASE WHEN m.loser_id IS NOT NULL THEN f.funder_id
 ELSE coalesce(f.merge_into_id,f.funder_id) END canonical_id
 FROM openalex.funders.nm1013_integrated_catalogue_after f
 LEFT JOIN openalex.funders.nm1013_integrated_merges m ON m.loser_id=f.funder_id),
alias_variants AS (
 SELECT canonical_id,lower(trim(nm)) k FROM f
 LATERAL VIEW explode(array_union(array(display_name),coalesce(from_json(alternate_titles,'array<string>'),array()))) a AS nm
), aliases AS (SELECT k,array_sort(collect_set(canonical_id)) targets FROM alias_variants WHERE k<>'' GROUP BY k),
keep_variants AS (
 SELECT f.canonical_id,lower(trim(k.name)) k FROM openalex.common.funder_names_keep k
 JOIN f ON f.funder_id=try_cast(regexp_extract(k.id,'([0-9]+)$',1) AS BIGINT)
), keeps AS (SELECT k,array_sort(collect_set(canonical_id)) targets FROM keep_variants WHERE k<>'' GROUP BY k),
names AS (
 SELECT k,targets FROM keeps
 UNION ALL SELECT a.k,a.targets FROM aliases a LEFT ANTI JOIN keeps k ON a.k=k.k
),
prod_ror_variants AS (
 SELECT canonical_id,lower(regexp_extract(trim(ror_id),r'(?i)^(?:https?://ror\.org/)?([0-9a-z]{9})/?$',1)) k FROM f
), registry_ror_variants AS (
 SELECT coalesce(f.canonical_id,r.funder_id) canonical_id,lower(regexp_extract(trim(r.id_value),r'(?i)^(?:https?://ror\.org/)?([0-9a-z]{9})/?$',1)) k
 FROM openalex.funders.nm1013_integrated_identifiers r
 LEFT JOIN openalex.funders.nm1013_integrated_merges tm ON tm.loser_id=r.origin_funder_id
 LEFT JOIN f ON f.funder_id=CASE WHEN tm.loser_id IS NOT NULL THEN r.origin_funder_id ELSE r.funder_id END WHERE r.id_type='ror'
), ror_variants AS (
 SELECT * FROM registry_ror_variants
 UNION ALL
 SELECT p.* FROM prod_ror_variants p LEFT ANTI JOIN registry_ror_variants r ON p.k=r.k
), rors AS (SELECT k,array_sort(collect_set(canonical_id)) targets FROM ror_variants WHERE k<>'' GROUP BY k),
-- (i) Every ROR name type is retained for candidate construction. A single
-- globally unique target is required. Standalone all-ROR matching failed 99%.
ror_names AS (
 SELECT lower(trim(n.value)) k,target funder_id
 FROM openalex.institutions.ror x JOIN rors r
 ON lower(regexp_extract(x.id,'([0-9a-z]{9})/*$',1))=r.k
 LATERAL VIEW explode(x.names) a AS n LATERAL VIEW explode(r.targets) b AS target
 WHERE trim(n.value)<>''
), dictionary AS (
 SELECT k,target funder_id FROM names LATERAL VIEW explode(targets) e AS target
 UNION ALL SELECT k,funder_id FROM ror_names
), normalized_variants AS (
 -- (ii) This normalization is used for hierarchy leaves only in the accepted
 -- ladder. Applying it to arbitrary whole strings failed the 99% criterion.
 SELECT trim(regexp_replace(regexp_replace(regexp_replace(translate(lower(replace(replace(replace(k,'&amp;','&'),'&apos;',char(39)),'&#39;',char(39))), 'áàâäãåāăąçćčďđéèêëēėęěíìîïīıłñńňóòôöõøōőřśšşťúùûüūůűýÿžźż', 'aaaaaaaaacccddeeeeeeeeiiiiiilnnnoooooooorssstuuuuuuuyyzzz'), '&', ' and '), r'[^\p{L}\p{N}]+', ' '), r'(^| )the( |$)', ' ')) nk,funder_id FROM dictionary
), normalized_names AS (
 SELECT nk,collect_set(funder_id) targets FROM normalized_variants
 WHERE length(nk)>=4 GROUP BY nk
),
twin_names AS (
 SELECT n.k,collect_set(coalesce(m.survivor_id,t)) targets,count_if(m.loser_id IS NOT NULL) changed
 FROM (SELECT k,explode(targets) t FROM names) n
 LEFT JOIN openalex.funders.nm1013_integrated_merges m ON m.loser_id=t
 GROUP BY n.k
), unique_rules AS (
 SELECT 'exact' rule,k name_key,get(targets,0) funder_id FROM names WHERE size(targets)=1
 UNION ALL SELECT 'hierarchy',nk,get(targets,0) FROM normalized_names WHERE size(targets)=1
 UNION ALL SELECT rule,name_key,funder_id FROM openalex.funders.nm1013_integrated_aliases
 UNION ALL SELECT 'twin',k,get(targets,0) FROM twin_names WHERE size(targets)=1 AND changed>0
)
SELECT u.rule,u.name_key,coalesce(f.merge_into_id,f.funder_id) funder_id
FROM unique_rules u
JOIN openalex.funders.nm1013_integrated_catalogue_after f ON f.funder_id=u.funder_id
JOIN openalex.funders.nm1013_integrated_catalogue_after target ON target.funder_id=coalesce(f.merge_into_id,f.funder_id)
WHERE target.merge_into_id IS NULL;

-- FILE 047_name_stage.sql
-- REVIEW ONLY; owner Rohan; each production action requires fresh authorization.
-- immutable release stage cell 6
CREATE TABLE openalex.funders.nm1013_integrated_lookup AS
SELECT l.*, 'openalex.funders.nm1013_integrated_' release_id,s.catalogue_signature FROM openalex.funders.nm1013_integrated_lookup_rows l
CROSS JOIN (SELECT concat(count(*), ':', cast(sum(cast(xxhash64(funder_id,display_name,alternate_titles,ror_id,doi,crossref_id,merge_into_id) AS DECIMAL(38,0))) AS STRING)) catalogue_signature FROM openalex.funders.nm1013_integrated_catalogue_after) s;
SELECT assert_true((SELECT count(*) FROM openalex.funders.nm1013_integrated_aliases)=204,'alias count'),
 assert_true((SELECT count(*) FROM (SELECT rule,name_key FROM openalex.funders.nm1013_integrated_lookup GROUP BY ALL HAVING count(*)<>1))=0,'ambiguous lookup');
SELECT assert_true(count(*)=0,'alias target absent from approved catalogue or lookup')
FROM openalex.funders.nm1013_integrated_aliases a
LEFT JOIN openalex.funders.nm1013_integrated_catalogue_after f ON f.funder_id=a.funder_id
LEFT JOIN openalex.funders.nm1013_integrated_lookup l ON l.rule=a.rule AND l.name_key=a.name_key AND l.funder_id=coalesce(f.merge_into_id,f.funder_id)
WHERE f.funder_id IS NULL OR l.funder_id IS NULL;

-- FILE 048_name_gate.sql
-- REVIEW ONLY; owner Rohan; each production action requires fresh authorization.
-- Require first activation and post-cutover view
SELECT assert_true(count(*)=0,'live name lookup already exists: new combined review required') FROM openalex.information_schema.tables WHERE table_schema='funders' AND table_name='funder_name_lookup';
SELECT assert_true(count(*)=1,'served funders must be a view') FROM openalex.information_schema.tables WHERE table_schema='funders' AND table_name='funders' AND table_type='VIEW';

-- FILE 058_name_activate.sql
SELECT assert_true(current_timestamp() >= to_timestamp(concat(:switch_day, ' 08:00:00 America/Los_Angeles')) AND current_timestamp() < to_timestamp(concat(:switch_day, ' 18:30:00 America/Los_Angeles')), '058 abort deadline reached: STOP and recover');
-- REVIEW ONLY; owner Rohan; each production action requires fresh authorization.
-- Registry then identifiers then compat then signed lookup; keep readers paused
-- Readers remain on main until the last publication statement. Operator keeps
-- their schedules paused during activation and restores them for the next night.
SELECT assert_true((SELECT count(*) FROM (
 (SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.funders EXCEPT ALL SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.nm1013_integrated_catalogue_before)
 UNION ALL (SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.nm1013_integrated_catalogue_before EXCEPT ALL SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.funders)
))=0,'catalogue changed since stage: restage and reapprove');
-- No-merge switch: registry, identifiers and compat must remain exact.
SELECT assert_true((SELECT count(*) FROM (
 (SELECT * FROM openalex.funders.funder EXCEPT ALL SELECT * FROM openalex.funders.nm1013_integrated_registry_before)
 UNION ALL (SELECT * FROM openalex.funders.nm1013_integrated_registry_before EXCEPT ALL SELECT * FROM openalex.funders.funder)))=0,'registry changed since stage');
SELECT assert_true((SELECT count(*) FROM (
 (SELECT * FROM openalex.funders.funder_id EXCEPT ALL SELECT * FROM openalex.funders.nm1013_integrated_identifiers_before)
 UNION ALL (SELECT * FROM openalex.funders.nm1013_integrated_identifiers_before EXCEPT ALL SELECT * FROM openalex.funders.funder_id)))=0,'identifier ownership changed since stage');
SELECT assert_true(count(*)=0 AND count_if(l.status<>'active' OR l.merged_into_id IS NOT NULL OR w.status<>'active' OR l.funder_id IS NULL OR w.funder_id IS NULL)=0,'registry merge preconditions')
FROM openalex.funders.nm1013_integrated_merges m
LEFT JOIN openalex.funders.funder l ON l.funder_id=m.loser_id
LEFT JOIN openalex.funders.funder w ON w.funder_id=m.survivor_id;
SELECT assert_true((SELECT count(*) FROM (
 (SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.funders EXCEPT ALL SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.nm1013_integrated_catalogue_after)
 UNION ALL (SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.nm1013_integrated_catalogue_after EXCEPT ALL SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.funders)
))=0,'catalogue publication mismatch: keep readers paused');
SELECT assert_true(count(*)=0,'funder activation mismatch: keep readers paused') FROM ((SELECT * FROM openalex.funders.funder EXCEPT ALL SELECT * FROM openalex.funders.nm1013_integrated_registry_after) UNION ALL (SELECT * FROM openalex.funders.nm1013_integrated_registry_after EXCEPT ALL SELECT * FROM openalex.funders.funder));
SELECT assert_true(count(*)=0,'funder_id activation mismatch: keep readers paused') FROM ((SELECT * FROM openalex.funders.funder_id EXCEPT ALL SELECT * FROM openalex.funders.nm1013_integrated_identifiers_after) UNION ALL (SELECT * FROM openalex.funders.nm1013_integrated_identifiers_after EXCEPT ALL SELECT * FROM openalex.funders.funder_id));
CREATE OR REPLACE TABLE openalex.funders.funder_name_lookup AS SELECT * FROM openalex.funders.nm1013_integrated_lookup;

-- FILE 059_republish.sql
-- REVIEW ONLY; owner Rohan; each production action requires fresh authorization.
-- Exact future publication must retain redirects and all fields
CREATE OR REPLACE TABLE openalex.funders.funders_compat AS
SELECT f.funder_id, CAST(get_json_object(v41.j, '$.crossref_id') AS BIGINT) crossref_id,
  get_json_object(v41.j, '$.location') location, f.display_name,
  CASE WHEN CASE WHEN v41.j IS NULL AND r.source_key IS NOT NULL THEN array_sort(array_distinct(concat(coalesce(f.alt_names, array()), coalesce(r.alt_names, array())))) ELSE f.alt_names END <=> from_json(get_json_object(v41.j, '$.alternate_titles'), 'array<string>') THEN get_json_object(v41.j, '$.alternate_titles') ELSE to_json(coalesce(CASE WHEN v41.j IS NULL AND r.source_key IS NOT NULL THEN array_sort(array_distinct(concat(coalesce(f.alt_names, array()), coalesce(r.alt_names, array())))) ELSE f.alt_names END, array())) END alternate_titles,
  get_json_object(v41.j, '$.uri') uri,
  coalesce(get_json_object(v41.j, '$.replaces'), CASE WHEN v41.j IS NULL THEN '[]' END) replaces,
  coalesce(get_json_object(v41.j, '$.replaced_by'), CASE WHEN v41.j IS NULL THEN '[]' END) replaced_by,
  get_json_object(v41.j, '$.tokens') tokens, CASE WHEN v41.j IS NOT NULL THEN get_json_object(v41.j, '$.ror_id') ELSE f.ror_id END ror_id,
  CASE WHEN f.status = 'merged' THEN f.merged_into_id END merge_into_id,
  CASE WHEN v41.j IS NOT NULL THEN CAST(get_json_object(v41.j, '$.merge_into_date') AS TIMESTAMP) WHEN f.status='merged' THEN f.updated_date END merge_into_date,
  coalesce(get_json_object(v41.j, '$.created_date'), CAST(f.created_date AS STRING)) created_date, f.wikidata_id,
  get_json_object(v41.j, '$.doi') doi,
  f.country_code, f.homepage_url, f.description, f.image_url, f.image_thumbnail_url, get_json_object(v41.j, '$.json_entity_hash') json_entity_hash, CASE WHEN v41.j IS NOT NULL THEN CAST(get_json_object(v41.j, '$.updated_date') AS TIMESTAMP) ELSE f.updated_date END updated_date
FROM openalex.funders.funder f
LEFT JOIN (SELECT CAST(source_key AS BIGINT) funder_id, record_json j FROM openalex.funders.funder_source_record WHERE source = 'openalex_v41') v41 ON v41.funder_id = f.funder_id
LEFT JOIN openalex.funders.funder_source_record r ON r.source = 'ror' AND r.source_key = lower(regexp_extract(f.ror_id, '([0-9a-z]{9})/*$', 1)) AND r.record_status <> 'gone'
WHERE f.status IN ('active', 'merged');

-- FILE 060_republish_gate.sql
-- REVIEW ONLY; owner Rohan; each production action requires fresh authorization.
-- Catalogue equals approved after image after second publish
SELECT count(*) differences,assert_true(count(*)=0,'republish undid names release') FROM ((SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.funders EXCEPT ALL SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.nm1013_integrated_catalogue_after) UNION ALL (SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.nm1013_integrated_catalogue_after EXCEPT ALL SELECT * EXCEPT(merge_into_id),merge_into_id FROM openalex.funders.funders));

-- FILE gofix/no-merge-api-gate.sql
-- No-merge switch: a deferred decision must never reach serving.
SELECT count(*) active_merges,assert_true(count(*)=0,'deferred merge activated: STOP') gate FROM openalex.funders.nm1013_integrated_merges;
WITH a AS (SELECT funder_id id FROM openalex.funders.funders WHERE merge_into_id IS NULL),
b AS (SELECT id FROM openalex.funders.funders_api)
SELECT count_if(a.id IS NULL) removed,count_if(b.id IS NULL) added,
 assert_true(count_if(a.id IS NULL OR b.id IS NULL)=0,'funder API membership changes in zero-merge switch: STOP') gate
FROM a FULL JOIN b USING(id);

-- FILE gofix/s0b_funder_identity_post_switch.sql
-- READ ONLY. s0b = s0 for AFTER the Funders switch-over (name fixes + no-DOI-forward), fold-ship Tue 10-13.
-- Names may change; identity may not. Compares only funder_id, merge_into_id, doi, ror_id, crossref_id of the ~30 pinned NIH ids against v41.
-- compat_hash / basis_hash are REPORTED, not gated: after the switch, pin the first post-switch values here and require them equal every morning.
--   post-switch compat_hash: ________   basis_hash: ________ (fill from the first s0b run after the switch is green)
WITH ids AS (
  SELECT DISTINCT CAST(get_json_object(evidence_json, '$.project_funder_id') AS BIGINT) funder_id FROM openalex_dev.rohan_lab.npy1007r_all_newest_manifest
    WHERE get_json_object(evidence_json, '$.project_funder_id') IS NOT NULL
  UNION SELECT funder_id FROM openalex_dev.rohan_lab.npy1007n_ic_map
  UNION SELECT explode(array(4320332161,4320337611,4320337356,4320337376,4320337472,4320337358,4320337593,4320337375,4320337355,4320337362,4320337363,4320337364,4320337365,4320337357,4320337361,4320337354,4320337346,4320337359,4320337353,4320337337,4320337330,4320337352,4320337347,4320337534,4320337372,4320337351,4320337374,4320337350,4320337338,4320337348))),
c AS (SELECT * FROM openalex.funders.funders c),
ref AS (SELECT * FROM openalex_dev.rohan_lab.funders_v41_ref),
m AS (SELECT
  (SELECT count(*) FROM ids) ids_checked,
  (SELECT count(*) FROM ids LEFT ANTI JOIN c USING(funder_id)) missing_in_compat,
  (SELECT count(*) FROM ids JOIN c USING(funder_id) WHERE c.merge_into_id IS NOT NULL) merged_in_compat,
  (SELECT count(*) FROM ids JOIN c USING(funder_id) JOIN ref r USING(funder_id) WHERE to_json(struct(c.funder_id,c.merge_into_id,c.doi,c.ror_id,c.crossref_id)) <> to_json(struct(r.funder_id,r.merge_into_id,r.doi,r.ror_id,r.crossref_id))) identity_differs_from_v41,
  (SELECT count(*) FROM c) compat_rows,
  (SELECT CAST(sum(CAST(xxhash64(to_json(struct(*))) AS DECIMAL(38,0))) AS STRING) FROM c) compat_hash,
  (SELECT count(*) FROM openalex.awards.award_funders_basis) basis_rows,                                            -- 43,762
  (SELECT CAST(sum(CAST(xxhash64(to_json(struct(*))) AS DECIMAL(38,0))) AS STRING) FROM openalex.awards.award_funders_basis) basis_hash)   -- -528848368602275172432
SELECT CASE WHEN missing_in_compat = 0 AND merged_in_compat = 0 AND identity_differs_from_v41 = 0
             THEN 'PASS' ELSE 'FAIL' END funder_inputs_ok, * FROM m

-- FILE gofix/s0b-pin.sql
SELECT assert_true(funder_inputs_ok='PASS' AND ids_checked=30 AND compat_rows=41864 AND compat_hash='-568336946169178197326' AND basis_rows=43762 AND basis_hash='-528848368602275172432','post-switch identity/hash drift: STOP') FROM (
-- READ ONLY. s0b = s0 for AFTER the Funders switch-over (name fixes + no-DOI-forward), fold-ship Tue 10-13.
-- Names may change; identity may not. Compares only funder_id, merge_into_id, doi, ror_id, crossref_id of the ~30 pinned NIH ids against v41.
-- compat_hash / basis_hash are REPORTED, not gated: after the switch, pin the first post-switch values here and require them equal every morning.
--   post-switch compat_hash: ________   basis_hash: ________ (fill from the first s0b run after the switch is green)
WITH ids AS (
  SELECT DISTINCT CAST(get_json_object(evidence_json, '$.project_funder_id') AS BIGINT) funder_id FROM openalex_dev.rohan_lab.npy1007r_all_newest_manifest
    WHERE get_json_object(evidence_json, '$.project_funder_id') IS NOT NULL
  UNION SELECT funder_id FROM openalex_dev.rohan_lab.npy1007n_ic_map
  UNION SELECT explode(array(4320332161,4320337611,4320337356,4320337376,4320337472,4320337358,4320337593,4320337375,4320337355,4320337362,4320337363,4320337364,4320337365,4320337357,4320337361,4320337354,4320337346,4320337359,4320337353,4320337337,4320337330,4320337352,4320337347,4320337534,4320337372,4320337351,4320337374,4320337350,4320337338,4320337348))),
c AS (SELECT * FROM openalex.funders.funders c),
ref AS (SELECT * FROM openalex_dev.rohan_lab.funders_v41_ref),
m AS (SELECT
  (SELECT count(*) FROM ids) ids_checked,
  (SELECT count(*) FROM ids LEFT ANTI JOIN c USING(funder_id)) missing_in_compat,
  (SELECT count(*) FROM ids JOIN c USING(funder_id) WHERE c.merge_into_id IS NOT NULL) merged_in_compat,
  (SELECT count(*) FROM ids JOIN c USING(funder_id) JOIN ref r USING(funder_id) WHERE to_json(struct(c.funder_id,c.merge_into_id,c.doi,c.ror_id,c.crossref_id)) <> to_json(struct(r.funder_id,r.merge_into_id,r.doi,r.ror_id,r.crossref_id))) identity_differs_from_v41,
  (SELECT count(*) FROM c) compat_rows,
  (SELECT CAST(sum(CAST(xxhash64(to_json(struct(*))) AS DECIMAL(38,0))) AS STRING) FROM c) compat_hash,
  (SELECT count(*) FROM openalex.awards.award_funders_basis) basis_rows,                                            -- 43,762
  (SELECT CAST(sum(CAST(xxhash64(to_json(struct(*))) AS DECIMAL(38,0))) AS STRING) FROM openalex.awards.award_funders_basis) basis_hash)   -- -528848368602275172432
SELECT CASE WHEN missing_in_compat = 0 AND merged_in_compat = 0 AND identity_differs_from_v41 = 0
             THEN 'PASS' ELSE 'FAIL' END funder_inputs_ok, * FROM m
);
